          }
        }
      },
      {
        "name": "eth1",
        "type": "iana-if-type:ethernetCsmacd",
        "phys-address": "00:0C:42:E5:B1:EA",
        "oper-status": "up",
        "statistics": {
          "discontinuity-time": "2015-10-24T17:11:29+02:00"
        },
        "ietf-ip:ipv4": {
          "forwarding": true,
          "mtu": 1500,
          "address": [
            {
              "ip": "198.51.100.1",
              "prefix-length": 24
            }
          ]
        },
        "ietf-ip:ipv6": {
          "forwarding": true,
          "mtu": 1500,
          "address": [
            {
              "ip": "2001:0db8:0:2::1",
              "prefix-length": 64
            }
