    "ribs": {
      "rib": [
        {
          "name": "ipv4-master",
          "address-family":
            "ietf-ipv4-unicast-routing:ipv4-unicast",
          "default-rib": true,
          "routes": {
            "route": [
              {
                "ietf-ipv4-unicast-routing:destination-prefix":
                  "192.0.2.1/24",
